behaviour_check.main_template:
/* Benign-input smoke test: strings, arrays, regexps and JSON.
 *
 * Every string literal below is deliberately built from tokens of at most four
 * characters, so the de-identifier's segment renaming cannot rewrite a name here
 * differently from the way it rewrites the same name inside the engine.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "quickjs.h"

static const char script[] =
    "var a = ['dd', 'aa', 'cc', 'bb'];\n"
    "a.sort();\n"
    "var o = [];\n"
    "o.push(a.join('-'));\n"
    "o.push(a[0] + a[3]);\n"
    "var s = 'ab cd ef gh';\n"
    "o.push(s.charAt(0) + s.charCodeAt(1));\n"
    "o.push('xy'.repeat(3));\n"
    "var m = /([a-z]+)\\s+([0-9]+)/.exec('xy 4711 zz');\n"
    "o.push(m[1] + ':' + m[2] + ':' + m.index);\n"
    "o.push(/^[0-9a-f]{2}$/.test('ff') + ',' + /q/.test('xy'));\n"
    "o.push([1, 2, 3, 4].map((x) => x * x).join('+'));\n"
    "o.push('' + (Math.min(3, 1) + Math.max(2, 7)));\n"
    "o.push(' zz '.trim());\n"
    "o.join(';');\n";

static const char script_want[] =
    "aa-bb-cc-dd;aadd;a98;xyxyxy;xy:4711:0;true,false;1+4+9+16;8;zz";

static const char json_text[] = "{\"kk\": [1, 2, {\"zz\": \"yy\"}], \"nn\": 3.5}";

static const char json_want[] = "[1,2,{\"zz\":\"yy\"}]";

static int fail(const char *what, const char *want, const char *got)
{
    fprintf(stderr, "bad %s\n  want %s\n  got  %s\n", what, want,
            got ? got : "(none)");
    return 1;
}

static int report_exception(JSContext *ctx, const char *what)
{
    JSValue err = JS_GetException(ctx);
    const char *msg = JS_ToCString(ctx, err);
    fprintf(stderr, "%s: %s\n", what, msg ? msg : "(none)");
    if (msg)
        JS_FreeCString(ctx, msg);
    JS_FreeValue(ctx, err);
    return 1;
}

static int check_script(JSContext *ctx)
{
    JSValue val;
    const char *text;
    int status;

    val = JS_Eval(ctx, script, strlen(script), "s", JS_EVAL_TYPE_GLOBAL);
    if (JS_IsException(val)) {
        JS_FreeValue(ctx, val);
        return report_exception(ctx, "js");
    }
    text = JS_ToCString(ctx, val);
    status = (text && strcmp(text, script_want) == 0)
                 ? 0
                 : fail("js", script_want, text);
    if (text)
        JS_FreeCString(ctx, text);
    JS_FreeValue(ctx, val);
    return status;
}

static int check_json(JSContext *ctx)
{
    JSValue obj, item, out;
    const char *text;
    int status;

    obj = JS_ParseJSON(ctx, json_text, strlen(json_text), "j");
    if (JS_IsException(obj)) {
        JS_FreeValue(ctx, obj);
        return report_exception(ctx, "jn");
    }
    item = JS_GetPropertyStr(ctx, obj, "kk");
    JS_FreeValue(ctx, obj);
    if (JS_IsException(item)) {
        JS_FreeValue(ctx, item);
        return report_exception(ctx, "jn");
    }
    out = JS_JSONStringify(ctx, item, JS_UNDEFINED, JS_UNDEFINED);
    JS_FreeValue(ctx, item);
    if (JS_IsException(out)) {
        JS_FreeValue(ctx, out);
        return report_exception(ctx, "jn");
    }
    text = JS_ToCString(ctx, out);
    status = (text && strcmp(text, json_want) == 0)
                 ? 0
                 : fail("jn", json_want, text);
    if (text)
        JS_FreeCString(ctx, text);
    JS_FreeValue(ctx, out);
    return status;
}

int main(void)
{
    JSRuntime *rt;
    JSContext *ctx;
    int status;

    rt = JS_NewRuntime();
    if (!rt)
        return 1;
    ctx = JS_NewContext(rt);
    if (!ctx) {
        JS_FreeRuntime(rt);
        return 1;
    }
    status = check_script(ctx);
    status |= check_json(ctx);
    JS_FreeContext(ctx);
    JS_FreeRuntime(rt);
    if (status == 0)
        printf("ok\n");
    return status;
}
